-- Blank2Branded BOBShop catalogue import from bobshop_feed_1.xml
-- Source: 13,359 variant records grouped into 795 products.
BEGIN;
SET LOCAL statement_timeout=0; SET LOCAL lock_timeout=0;
DELETE FROM public.shop_product_variants WHERE product_id IN (SELECT id FROM public.shop_products WHERE supplier_item_number IS NOT NULL);
DELETE FROM public.shop_product_images WHERE product_id IN (SELECT id FROM public.shop_products WHERE supplier_item_number IS NOT NULL);
UPDATE public.shop_products p SET base_price=s.min_price FROM (SELECT product_id,MIN(price) min_price FROM public.shop_product_variants GROUP BY product_id) s WHERE p.id=s.product_id;
COMMIT;
